def search(query, documents):
    matches = [d for d in documents if query in d["terms"]]
    return sorted(matches, key=lambda d: d["rank"])[:20]

def search(query, index, decode):
    hits = index.lookup(query)
    return [(decode(h), decode(h)["rank"]) for h in hits]

def encode(document):
    return tuple(sorted(set(document["terms"])))

def score(encoded, query):
    return len(set(encoded) & set(query["terms"]))
